def test_create_product_with_missing_category(
    client,
    db_session,
):
    headers = create_admin_headers(
        client,
        db_session,
    )

    response = client.post(
        PRODUCTS_URL,
        json=product_payload(999999),
        headers=headers,
    )

    assert response.status_code == 404
