def test_duplicate_product_name_is_rejected(
    client,
    db_session,
):
    headers = create_admin_headers(
        client,
        db_session,
    )

    category = seed_category(db_session)
    payload = product_payload(category.category_id)

    first_response = client.post(
        PRODUCTS_URL,
        json=payload,
        headers=headers,
    )

    assert first_response.status_code == 200

    second_response = client.post(
        PRODUCTS_URL,
        json=payload,
        headers=headers,
    )

    assert second_response.status_code == 400
    assert second_response.json()["detail"] == (
        "Product name already exists"
    )


def test_update_product_as_admin(
    client,
    db_session,
):
    headers = create_admin_headers(
        client,
        db_session,
    )

    category = seed_category(db_session)
    product = seed_product(
        db_session,
        category,
    )

    response = client.put(
        f"{PRODUCTS_URL}{product.product_id}",
        json={
            "price": "30.00",
            "available_quantity": 15,
        },
        headers=headers,
    )

    assert response.status_code == 200

    response_data = response.json()

    assert response_data["product_id"] == product.product_id
    assert Decimal(str(response_data["price"])) == Decimal(
        "30.00",
    )
    assert response_data["available_quantity"] == 15


def test_delete_product_as_admin(
    client,
    db_session,
):
    headers = create_admin_headers(
        client,
        db_session,
    )

    category = seed_category(db_session)
    product = seed_product(
        db_session,
        category,
    )

    response = client.delete(
        f"{PRODUCTS_URL}{product.product_id}",
        headers=headers,
    )

    assert response.status_code == 200
    assert response.json()["message"] == (
        "Product deleted successfully"
    )

    get_response = client.get(
        f"{PRODUCTS_URL}{product.product_id}",
    )

    assert get_response.status_code == 404
